"""
    test for y < x < z with tupples
    :param x:
    :param y:
    :param z:
    :return:
    """
def colorinterval(x: Any, y: Any, z: Any) -> object {
    a = y[0] <= x[0] <= z[0];
    b = y[1] <= x[1] <= z[1];
    c = y[1] <= x[1] <= z[1];
    return (a and b and c);
}

